void main(void)
{
	uint32_t x, r, g, b;
	unsigned char *fb = ((unsigned char*)VGA_ADDR);

	VGA_CTRL = VGA_CTRL_GFX_MODE;
	for (x = 0; x < 64000; x++) {
		r = lt1000_img.pixel_data[3*x + 0] >> 5;
		g = lt1000_img.pixel_data[3*x + 1] >> 5;
		b = lt1000_img.pixel_data[3*x + 2] >> 6;
		fb[x] = (r << 5) | (g << 2) | b;
	}

	getch();
}
